<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {displayDate,journalRow,money} from '../../lib/expenditure-domain';
const props=defineProps({journal:Object,loading:Boolean,busy:Boolean,error:String,notice:String});const open=defineModel({type:Boolean,default:false}),date=defineModel('date',{type:String});const emit=defineEmits(['save']);
const root=ref(null),closeButton=ref(null),rows=computed(()=>(props.journal?.rows||[]).map(journalRow)),debit=computed(()=>rows.value.reduce((s,r)=>s+(Number(r.debit)||0),0)),credit=computed(()=>rows.value.reduce((s,r)=>s+(Number(r.credit)||0),0)),balanced=computed(()=>Math.abs(debit.value-credit.value)<.005);let focus,overflow;
watch(open,async value=>{if(value){focus=document.activeElement;overflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();closeButton.value?.focus();}else{document.body.style.overflow=overflow??'';focus?.focus();}});
function keydown(e){if(!open.value)return;if(e.key==='Escape'&&!props.busy)open.value=false;if(e.key==='Tab'){const items=[...root.value.querySelectorAll('button,input,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
onMounted(()=>document.addEventListener('keydown',keydown));onBeforeUnmount(()=>{document.removeEventListener('keydown',keydown);if(open.value)document.body.style.overflow=overflow??'';});
</script>
<template><div v-if="open" class="life-exp-jv-overlay" @click.self="!busy&&(open=false)"><section ref="root" class="life-exp-jv-modal" role="dialog" aria-modal="true" aria-labelledby="expJVTitle"><header class="jv-head"><div class="jv-icon" aria-hidden="true">≡</div><div class="jv-head-copy"><div class="jv-kicker">Branch Expenditure</div><h3 id="expJVTitle">Journal Entry</h3></div><button ref="closeButton" type="button" class="jv-close" aria-label="Close Journal Entry" :disabled="busy" @click="open=false">×</button></header><div class="jv-body"><div class="jv-info"><template v-if="journal"><span class="jv-doc-id">{{journal.name}}</span><span class="jv-pill">{{journal.branch}}</span><span class="jv-pill">{{displayDate(journal.posting_date)}}</span><span class="jv-pill jv-state">{{journal.docstatus===1?'Submitted':journal.docstatus===0?'Draft':'Cancelled'}}</span></template><template v-else>{{loading?'Loading Journal Entry…':'Unable to load JV'}}</template></div><template v-if="journal"><div v-if="journal.can_edit_date" class="jv-date-controls"><label class="jv-date-label">Change Posting Date<input v-model="date" class="jv-new-date" type="date" :max="journal.today" :disabled="busy"></label><button class="jv-save-date" type="button" :disabled="busy" @click="emit('save')">{{busy?'Saving…':'Submit Date Change'}}</button></div><p class="jv-notice">{{journal.can_edit_date?journal.docstatus===1?'Date changes create an amended JV and retain its amounts and cost centers. Accounting-period restrictions apply.':'The new date will be saved to this draft.':'View only · Posting dates can be changed by Accounts Manager users.'}}</p><div class="jv-summary"><div class="jv-stat"><span class="jv-stat-label">Total Debit</span><strong class="jv-total-debit">{{money(debit)}}</strong></div><div class="jv-stat"><span class="jv-stat-label">Total Credit</span><strong class="jv-total-credit">{{money(credit)}}</strong></div><span class="jv-balance-chip" :style="{color:balanced?'#227140':'#a43f32'}">{{balanced?'✓ Balanced':'Difference '+money(Math.abs(debit-credit))}}</span></div><div class="jv-table-title"><span>Accounting Entries</span><span class="jv-row-count">{{rows.length}} ledger rows</span></div><div class="jv-table-wrap"><table><colgroup><col style="width:25%"><col style="width:16%"><col style="width:13%"><col style="width:13%"><col style="width:22%"><col style="width:11%"></colgroup><thead><tr><th>Account</th><th>Cost Center</th><th class="jv-num">Debit</th><th class="jv-num">Credit</th><th>Remarks</th><th>Bill</th></tr></thead><tbody class="jv-rows"><tr v-for="(r,i) in rows" :key="r.name||i"><td class="jv-account">{{r.account||'—'}}</td><td>{{r.cost_center||'—'}}</td><td class="jv-num" :class="Number(r.debit)?'jv-debit':'jv-zero'">{{Number(r.debit)?money(r.debit):'—'}}</td><td class="jv-num" :class="Number(r.credit)?'jv-credit':'jv-zero'">{{Number(r.credit)?money(r.credit):'—'}}</td><td>{{r.remarks||'—'}}</td><td><a v-if="r.bill" class="jv-bill" :href="r.bill" target="_blank" rel="noopener noreferrer">↗ View bill</a><span v-else class="jv-zero">—</span></td></tr></tbody></table></div></template></div><footer class="jv-foot"><p class="jv-error" :role="error?'alert':'status'">{{error||notice}}</p><a v-if="journal" class="jv-erp-link" :href="'/app/journal-entry/'+encodeURIComponent(journal.name)" target="_blank" rel="noopener noreferrer">Open in ERPNext ↗</a></footer></section></div></template>
